import { test, expect } from '@playwright/test';

test.describe('Async Operation Cancellation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000'); // Replace with your app's URL
  });

  test('should start async operation', async ({ page }) => {
    await page.getByRole('button', { name: 'Start Async Operation' }).click();
    const status = await page.getByText('Operation in progress...');
    await expect(status).toBeVisible();
  });

  test('should cancel async operation', async ({ page }) => {
    await page.getByRole('button', { name: 'Start Async Operation' }).click();
    await page.getByRole('button', { name: 'Abort' }).click();
    const status = await page.getByText('Operation cancelled');
    await expect(status).toBeVisible();
  });
});
